-- =============================================================================
-- Grammar seed lessons (spec: .kiro/specs/grammar/tasks.md task 6)
-- One published lesson per level: A2 articles, B1 present perfect vs past simple,
-- B2 2nd vs 3rd conditional (from the prototype) and C1 inversion. Each is added
-- only if its id is free, at the end of its level's course (position 1 when empty).
-- content: the stored body (lesson-format.md with every text as {"en": ...}).
-- =============================================================================

insert into grammar_lesson (slug, level, topic_key, title, position, status, revision, version, content, published_at)
select 'a2-articles-1', 'A2', 'articles', 'Articles: a / an / the',
       coalesce((select max(position) from grammar_lesson where level = 'A2' and status = 'PUBLISHED'), 0) + 1,
       'PUBLISHED', 1, 0, '{"level":"A2","topic":{"key":"articles","label":{"en":"Articles"}},"title":{"en":"Articles: a / an / the"},"goal":{"en":"By the end, you’ll know how to decide a, an, the — or no article — and produce them yourself."},"minutes":20,"learn":[{"icon":"📦","label":{"en":"The idea"},"heading":{"en":"“a / an” = one, not specific"},"body":{"en":"Use <b>a / an</b> for <b>one of many</b>, when the listener doesn’t know which."},"examples":[{"ok":true,"text":{"en":"I saw <b>a</b> dog."}},{"ok":true,"text":{"en":"She is <b>an</b> engineer."}}]},{"icon":"🔊","label":{"en":"a vs an"},"heading":{"en":"Follow the sound"},"body":{"en":"<b>a</b> + consonant sound, <b>an</b> + vowel sound."},"examples":[{"ok":true,"text":{"en":"<b>a</b> university"}},{"ok":true,"text":{"en":"<b>an</b> hour"}}]},{"icon":"🎯","label":{"en":"the"},"heading":{"en":"We both know which one"},"body":{"en":"Use <b>the</b> for something specific or unique."},"examples":[{"ok":true,"text":{"en":"<b>The</b> sun is bright."}},{"ok":true,"text":{"en":"Close <b>the</b> door."}}]},{"icon":"🚫","label":{"en":"The trap"},"heading":{"en":"No a/an with uncountable words"},"body":{"en":"<b>advice, information, water</b> take no a/an."},"examples":[{"ok":false,"text":{"en":"an <b>advice</b>"}},{"ok":true,"text":{"en":"some <b>advice</b>"}}]},{"icon":"🧭","label":{"en":"How to decide"},"heading":{"en":"Ask 3 questions, in order"},"steps":[{"en":"1️⃣ Is the noun <b>uncountable</b>? (advice, water, information) → <b>no a/an</b>"},{"en":"2️⃣ Is it <b>specific / the only one</b>? → <b>the</b>"},{"en":"3️⃣ One of many? → <b>a</b> (consonant sound) or <b>an</b> (vowel sound)"}],"tip":{"en":"Work from the top: stop at the first “yes”."}}],"worked":{"question":{"en":"Choose the article: “___ hour”."},"steps":[{"en":"🔊 Say it: <b>hour</b> — the “h” is silent."},{"en":"🎯 So it starts with a <b>vowel sound</b> (ow-er), even though the letter is a consonant."},{"en":"✅ Vowel sound → <b>an</b>."}],"answer":"an hour"},"practice":[{"id":"p1","type":"choose","prompt":{"en":"This is ___ apple."},"options":["a","an"],"answer":1,"whys":[{"en":"“apple” begins with a vowel sound, so “a” sounds wrong"},{"en":"✓ vowel sound → an"}],"explanation":{"en":"Vowel sound → <b>an</b>."}},{"id":"p2","type":"choose","prompt":{"en":"I can see ___ moon tonight."},"options":["a","the"],"answer":1,"whys":[{"en":"there’s only one moon, so it isn’t “one of many”"},{"en":"✓ unique → the"}],"explanation":{"en":"Only one moon → <b>the</b>."}},{"id":"p3","type":"build","prompt":{"en":"Put the words in order:"},"tiles":["engineer","an","She","is"],"answer":"She is an engineer","explanation":{"en":"“engineer” has a vowel sound → <b>an</b>."}}],"check":[{"id":"c1","type":"choose","prompt":{"en":"She is ___ honest person."},"options":["a","an","the","—"],"answer":1,"whys":[{"en":"the letter is a consonant, but the h is silent"},{"en":"✓ silent h = vowel sound → an"},{"en":"“the” would mean one specific person"},{"en":"a noun like this needs an article"}],"explanation":{"en":"Silent h → vowel sound → <b>an</b>."}},{"id":"c2","type":"choose","prompt":{"en":"I need ___ information first."},"options":["a","an","the","no article"],"answer":3,"whys":[{"en":"“information” is uncountable — no “a”"},{"en":"uncountable — no “an” either"},{"en":"“the” would point to specific information"},{"en":"✓ uncountable + general → no article"}],"explanation":{"en":"Uncountable → <b>no article</b>."}},{"id":"c3","type":"type","prompt":{"en":"Type <b>a</b> or <b>an</b>:"},"sentence":"___ umbrella","accept":["an"],"explanation":{"en":"Vowel sound → <b>an</b>."}},{"id":"c4","type":"type","prompt":{"en":"Type <b>a</b> or <b>an</b>:"},"sentence":"___ university","accept":["a"],"explanation":{"en":"“yu” is a consonant sound → <b>a</b>."}},{"id":"c5","type":"choose","prompt":{"en":"___ moon looks beautiful."},"options":["A","An","The","—"],"answer":2,"whys":[{"en":"the moon is unique, not “one of many”"},{"en":"same — unique things don’t take a/an"},{"en":"✓ unique → The"},{"en":"a subject noun needs an article here"}],"explanation":{"en":"Unique → <b>The</b>."}},{"id":"c6","type":"build","prompt":{"en":"Build the sentence:"},"tiles":["the","Close","please","door"],"answer":"Close the door please","explanation":{"en":"A specific door → <b>the</b>."}},{"id":"c7","type":"choose","prompt":{"en":"He wants ___ new phone."},"options":["a","an","the","—"],"answer":0,"whys":[{"en":"✓ one, not specific, consonant sound → a"},{"en":"“phone” starts with a consonant sound, not a vowel"},{"en":"“the” = a specific phone, but this one is new/any"},{"en":"a countable noun needs an article"}],"explanation":{"en":"One, not specific, consonant sound → <b>a</b>."}}]}'::jsonb, now()
where not exists (select 1 from grammar_lesson where slug = 'a2-articles-1');

insert into grammar_lesson (slug, level, topic_key, title, position, status, revision, version, content, published_at)
select 'b1-present-perfect-past-simple-1', 'B1', 'present-perfect', 'Present Perfect vs Past Simple',
       coalesce((select max(position) from grammar_lesson where level = 'B1' and status = 'PUBLISHED'), 0) + 1,
       'PUBLISHED', 1, 0, '{"level":"B1","topic":{"key":"present-perfect","label":{"en":"Present perfect vs past simple"}},"title":{"en":"Present Perfect vs Past Simple"},"goal":{"en":"By the end, you’ll know how to decide present perfect vs past simple — and produce both."},"minutes":20,"learn":[{"icon":"🌉","label":{"en":"The idea"},"heading":{"en":"Present perfect links past to NOW"},"body":{"en":"<b>have/has + past participle</b>. The connection to now matters, not the exact time."},"examples":[{"ok":true,"text":{"en":"I <b>have lost</b> my keys. (I can’t find them now)"}}]},{"icon":"✅","label":{"en":"When to use it"},"heading":{"en":"Experience · unfinished time · recent result"},"body":{"en":"Signals: <b>ever, never, just, already, yet, since, for</b>."},"examples":[{"ok":true,"text":{"en":"I <b>have been</b> to Paris."}},{"ok":true,"text":{"en":"We’ve known him <b>since</b> 2019."}}]},{"icon":"📅","label":{"en":"Past simple"},"heading":{"en":"Finished action, finished time"},"body":{"en":"Signals: <b>yesterday, ago, last week, in 2020</b>."},"examples":[{"ok":true,"text":{"en":"I <b>saw</b> him <b>yesterday</b>."}}]},{"icon":"⚠️","label":{"en":"The trap"},"heading":{"en":"Finished time → never present perfect"},"body":{"en":"A finished-time word blocks the present perfect."},"examples":[{"ok":false,"text":{"en":"I <b>have seen</b> him yesterday."}},{"ok":true,"text":{"en":"I <b>saw</b> him yesterday."}}]},{"icon":"🧭","label":{"en":"How to decide"},"heading":{"en":"Ask 2 questions, in order"},"steps":[{"en":"1️⃣ Is there a <b>finished-time word</b>? (yesterday, ago, in 2020, last week) → <b>Past simple</b>"},{"en":"2️⃣ No finished time, but <b>since / for / ever / just / already / yet</b>? → <b>Present perfect</b>"}],"tip":{"en":"Check the time words first — they decide it."}}],"worked":{"question":{"en":"Choose the verb: “I ___ (visit) London in 2019.”"},"steps":[{"en":"🔍 Find the time clue: <b>in 2019</b>."},{"en":"📅 Is that time finished? <b>Yes</b> — 2019 is over."},{"en":"✅ Finished time → <b>past simple</b>: visited."}],"answer":"visited"},"practice":[{"id":"p1","type":"choose","prompt":{"en":"I ___ my wallet — I can’t find it!"},"options":["lost","have lost"],"answer":1,"whys":[{"en":"“lost” = finished past, but the result (can’t find it) matters right now"},{"en":"✓ result affects now → present perfect"}],"explanation":{"en":"Result matters now → present perfect."}},{"id":"p2","type":"choose","prompt":{"en":"Shakespeare ___ many plays."},"options":["has written","wrote"],"answer":1,"whys":[{"en":"he’s no longer alive, so it’s a finished period — not present perfect"},{"en":"✓ finished life/time → past simple"}],"explanation":{"en":"His life is finished → past simple."}},{"id":"p3","type":"type","prompt":{"en":"Type the correct form of “finish”:"},"sentence":"She ___ her homework yesterday.","accept":["finished"],"explanation":{"en":"“yesterday” = finished time → <b>finished</b>."}},{"id":"p4","type":"build","prompt":{"en":"Put the words in order:"},"tiles":["been","to","I","Paris","have"],"answer":"I have been to Paris","explanation":{"en":"Life experience → present perfect."}}],"check":[{"id":"c1","type":"choose","prompt":{"en":"I ___ to Japan twice in my life."},"options":["went","have been","have gone","was"],"answer":1,"whys":[{"en":"“went” needs a finished time (e.g. last year); here it’s life experience"},{"en":"✓ life experience, no finished time → have been"},{"en":"“have gone” means still away / on the way, not “visited”"},{"en":"“was” can’t take “to Japan” this way"}],"explanation":{"en":"Life experience → <b>have been</b>."}},{"id":"c2","type":"type","prompt":{"en":"Type the correct form of “win”:"},"sentence":"They ___ the title in 2021.","accept":["won"],"explanation":{"en":"“in 2021” = finished time → <b>won</b>."}},{"id":"c3","type":"choose","prompt":{"en":"She ___ her homework yesterday."},"options":["has finished","finished","has finish","have finished"],"answer":1,"whys":[{"en":"“yesterday” is finished → present perfect is blocked"},{"en":"✓ finished time → past simple"},{"en":"“has finish” is not a valid form"},{"en":"wrong agreement (she → has, not have)"}],"explanation":{"en":"“yesterday” → past simple."}},{"id":"c4","type":"type","prompt":{"en":"Type the missing words (negative of “see”):"},"sentence":"We ___ her since Monday.","accept":["haven''t seen","have not seen"],"explanation":{"en":"“since” → present perfect; negative → <b>haven’t seen</b>."},"show":"haven''t seen"},{"id":"c5","type":"build","prompt":{"en":"Build the sentence:"},"tiles":["known","have","We","since","him","2019"],"answer":"We have known him since 2019","explanation":{"en":"“since” → present perfect."}},{"id":"c6","type":"fix","prompt":{"en":"This sentence is wrong. Type the correct verb (one word):"},"wrong":"I have seen him yesterday.","accept":["saw"],"explanation":{"en":"“yesterday” blocks present perfect → <b>saw</b>."}},{"id":"c7","type":"choose","prompt":{"en":"___ you ever been to Rome?"},"options":["Did","Have","Do","Were"],"answer":1,"whys":[{"en":"“Did … been” mixes past simple with a participle"},{"en":"✓ “ever” + experience → Have you ever been"},{"en":"“Do … been” is not a valid form"},{"en":"“Were you ever to Rome” isn’t used this way"}],"explanation":{"en":"“ever” = experience → <b>Have</b>."}},{"id":"c8","type":"type","prompt":{"en":"Type the correct form of “have”:"},"sentence":"We ___ dinner an hour ago.","accept":["had"],"explanation":{"en":"“ago” = finished time → <b>had</b>."}},{"id":"c9","type":"build","prompt":{"en":"Build the sentence:"},"tiles":["just","She","left","has"],"answer":"She has just left","explanation":{"en":"“just” → present perfect; it sits between has and the participle."}},{"id":"c10","type":"fix","prompt":{"en":"This is wrong. Type the correct verb form (one word):"},"wrong":"She has finished it yesterday.","accept":["finished"],"explanation":{"en":"“yesterday” → past simple → <b>finished</b>."}}]}'::jsonb, now()
where not exists (select 1 from grammar_lesson where slug = 'b1-present-perfect-past-simple-1');

insert into grammar_lesson (slug, level, topic_key, title, position, status, revision, version, content, published_at)
select 'b2-second-third-conditional-1', 'B2', 'conditionals', '2nd vs 3rd Conditional',
       coalesce((select max(position) from grammar_lesson where level = 'B2' and status = 'PUBLISHED'), 0) + 1,
       'PUBLISHED', 1, 0, '{"level":"B2","topic":{"key":"conditionals","label":{"en":"Conditionals"}},"title":{"en":"2nd vs 3rd Conditional"},"goal":{"en":"By the end, you’ll know how to decide 2nd vs 3rd conditional — and produce both cleanly."},"minutes":20,"learn":[{"icon":"💭","label":{"en":"2nd conditional"},"heading":{"en":"Unreal present / future"},"body":{"en":"<b>if + past simple</b> → <b>would + base</b>."},"examples":[{"ok":true,"text":{"en":"If I <b>had</b> time, I <b>would help</b>."}}]},{"icon":"⏮️","label":{"en":"3rd conditional"},"heading":{"en":"Unreal past (regret)"},"body":{"en":"<b>if + past perfect</b> → <b>would have + participle</b>."},"examples":[{"ok":true,"text":{"en":"If I <b>had had</b> time, I <b>would have helped</b>."}}]},{"icon":"🔒","label":{"en":"Golden rule"},"heading":{"en":"No “would” in the if-clause"},"body":{"en":"Keep would / would have in the result half only."},"examples":[{"ok":false,"text":{"en":"If I <b>would have</b> known…"}},{"ok":true,"text":{"en":"If I <b>had</b> known…"}}]},{"icon":"🧷","label":{"en":"Fixed phrase"},"heading":{"en":"“If I were you…”"},"body":{"en":"Use <b>were</b> for all subjects in careful English."},"examples":[{"ok":true,"text":{"en":"If I <b>were</b> you, I would apply."}}]},{"icon":"🧭","label":{"en":"How to decide"},"heading":{"en":"Ask 1 question"},"steps":[{"en":"1️⃣ Is it about the <b>past</b> (a regret, it can’t change)? → <b>3rd</b>: had + p.p. … would have + p.p."},{"en":"2️⃣ Is it about <b>now / the future</b> (imaginary)? → <b>2nd</b>: past simple … would + base"}],"tip":{"en":"And never put “would” in the if-clause."}}],"worked":{"question":{"en":"Complete: “If I ___ (know), I would have told you.”"},"steps":[{"en":"🔍 Look at the result: <b>would have told</b> → this is about the <b>past</b>."},{"en":"⏮️ Past + unreal → <b>3rd conditional</b>."},{"en":"✅ If-clause = <b>past perfect</b>: had known. (never “would have” in the if-clause)"}],"answer":"had known"},"practice":[{"id":"p1","type":"choose","prompt":{"en":"If I ___ taller, I would play basketball."},"options":["were","had been"],"answer":0,"whys":[{"en":"✓ imaginary now → 2nd conditional, were"},{"en":"“had been” is for the past (3rd conditional)"}],"explanation":{"en":"Unreal present → 2nd conditional <b>were</b>."}},{"id":"p2","type":"choose","prompt":{"en":"If they had left earlier, they ___ the train."},"options":["would catch","would have caught"],"answer":1,"whys":[{"en":"“would catch” is 2nd (now); but “had left” points to the past"},{"en":"✓ unreal past → would have caught"}],"explanation":{"en":"Unreal past → 3rd conditional."}},{"id":"p3","type":"build","prompt":{"en":"Put the words in order:"},"tiles":["you","were","I","If"],"answer":"If I were you","explanation":{"en":"Fixed phrase: <b>If I were you</b>."}}],"check":[{"id":"c1","type":"choose","prompt":{"en":"If I had known, I ___ earlier."},"options":["would come","would have come","will come","came"],"answer":1,"whys":[{"en":"“would come” is 2nd conditional, but “had known” is past"},{"en":"✓ unreal past → would have come"},{"en":"“will come” is for a real future"},{"en":"“came” drops the “would have”"}],"explanation":{"en":"3rd conditional → <b>would have come</b>."}},{"id":"c2","type":"choose","prompt":{"en":"If I ___ you, I would apologise."},"options":["am","was","were","will be"],"answer":2,"whys":[{"en":"“am” is real/present, but this is hypothetical"},{"en":"“was” is common in speech, but “were” is the careful IELTS form"},{"en":"✓ fixed phrase → If I were you"},{"en":"“will be” is future, not hypothetical"}],"explanation":{"en":"Fixed phrase → <b>were</b>."}},{"id":"c3","type":"choose","prompt":{"en":"Which sentence is correct?"},"options":["If it would rain, we would stay home.","If it rained, we would stay home."],"answer":1,"whys":[{"en":"“would” in the if-clause is the classic mistake"},{"en":"✓ if-clause keeps past simple → correct"}],"explanation":{"en":"No “would” in the if-clause."}},{"id":"c4","type":"type","prompt":{"en":"Type the correct form of “study”:"},"sentence":"If she ___ harder, she would have passed.","accept":["had studied"],"explanation":{"en":"Past regret → 3rd conditional → <b>had studied</b>."}},{"id":"c5","type":"type","prompt":{"en":"Type the correct form of “have”:"},"sentence":"If I ___ more money, I would travel.","accept":["had"],"explanation":{"en":"Unreal present → 2nd conditional past simple → <b>had</b>."}},{"id":"c6","type":"build","prompt":{"en":"Finish the 3rd conditional result — “If you had asked, …”"},"tiles":["have","I","would","helped"],"answer":"I would have helped","explanation":{"en":"Result half = would have + participle."}},{"id":"c7","type":"fix","prompt":{"en":"Wrong conditional. Type the correct if-clause verb (two words):"},"wrong":"If I would have known, I would have called.","accept":["had known"],"explanation":{"en":"No “would” in the if-clause → <b>had known</b>."}},{"id":"c8","type":"choose","prompt":{"en":"If we ___ now, we would catch the bus."},"options":["left","had left","would leave"],"answer":0,"whys":[{"en":"✓ imaginary present → 2nd conditional, left"},{"en":"“had left” would make it past (3rd conditional)"},{"en":"no “would” in the if-clause"}],"explanation":{"en":"Unreal present → 2nd conditional <b>left</b>."}}]}'::jsonb, now()
where not exists (select 1 from grammar_lesson where slug = 'b2-second-third-conditional-1');

insert into grammar_lesson (slug, level, topic_key, title, position, status, revision, version, content, published_at)
select 'c1-inversion-1', 'C1', 'inversion', 'Inversion after negative adverbials',
       coalesce((select max(position) from grammar_lesson where level = 'C1' and status = 'PUBLISHED'), 0) + 1,
       'PUBLISHED', 1, 0, '{"level":"C1","topic":{"key":"inversion","label":{"en":"Inversion"}},"title":{"en":"Inversion after negative adverbials"},"goal":{"en":"By the end, you’ll know when to invert after Never, Rarely, Not only… — and build these sentences yourself."},"minutes":20,"learn":[{"icon":"🔄","label":{"en":"The idea"},"heading":{"en":"Negative adverbial first → question word order"},"body":{"en":"Put a negative or limiting word at the start for emphasis, then use <b>auxiliary + subject</b>, like in a question."},"examples":[{"ok":true,"text":{"en":"<b>Never have I</b> seen such a view."}},{"ok":true,"text":{"en":"<b>Rarely does she</b> complain."}}]},{"icon":"🧩","label":{"en":"Which words"},"heading":{"en":"The adverbials that trigger it"},"body":{"en":"<b>Never, Rarely, Seldom, Hardly … when, No sooner … than, Not only … but also, Under no circumstances, Only later</b>."},"examples":[{"ok":true,"text":{"en":"<b>No sooner had</b> we arrived <b>than</b> it started to rain."}},{"ok":true,"text":{"en":"<b>Not only did</b> he apologise, <b>but</b> he <b>also</b> paid for the damage."}}]},{"icon":"⚙️","label":{"en":"No auxiliary?"},"heading":{"en":"Add do / does / did"},"body":{"en":"Present and past simple have no auxiliary, so add <b>do / does / did</b> and use the base verb."},"examples":[{"ok":false,"text":{"en":"Rarely she complains."}},{"ok":true,"text":{"en":"Rarely <b>does she complain</b>."}}]},{"icon":"⚠️","label":{"en":"The trap"},"heading":{"en":"Only after / Not until → invert the second clause"},"body":{"en":"With <b>Only after…</b>, <b>Only when…</b> and <b>Not until…</b> the inversion comes in the <b>main</b> clause, not straight after the adverbial."},"examples":[{"ok":true,"text":{"en":"Only after the meeting <b>did I understand</b> the problem."}},{"ok":false,"text":{"en":"Only after <b>did the meeting end</b>, I understood."}}]},{"icon":"🧭","label":{"en":"How to decide"},"heading":{"en":"Ask 3 questions, in order"},"steps":[{"en":"1️⃣ Does the sentence start with a <b>negative or limiting adverbial</b>? No → normal word order."},{"en":"2️⃣ Is there an <b>auxiliary</b> (have, be, can, will, should…)? → put it <b>before the subject</b>."},{"en":"3️⃣ No auxiliary (present / past simple)? → add <b>do / does / did</b> + base verb."}],"tip":{"en":"With Only after / Not until, invert the main clause."}}],"worked":{"question":{"en":"Rewrite: “I have never seen such a mess.” → “Never ___ such a mess.”"},"steps":[{"en":"🔍 It starts with <b>Never</b> → invert."},{"en":"⚙️ The auxiliary is <b>have</b> → put it before the subject: <b>have I</b>."},{"en":"✅ Never <b>have I seen</b> such a mess."}],"answer":"have I seen"},"practice":[{"id":"p1","type":"choose","prompt":{"en":"Rarely ___ such a talented student."},"options":["I have met","have I met"],"answer":1,"whys":[{"en":"normal word order after “Rarely” is the mistake"},{"en":"✓ negative adverbial first → have + I"}],"explanation":{"en":"“Rarely” at the start → <b>have I met</b>."}},{"id":"p2","type":"type","prompt":{"en":"Type the missing words (“she / complain”, present simple):"},"sentence":"Seldom ___ about her work.","accept":["does she complain"],"explanation":{"en":"No auxiliary in present simple → add <b>does</b>: <b>does she complain</b>."}},{"id":"p3","type":"build","prompt":{"en":"Build the sentence start:"},"tiles":["had","No","arrived","sooner","we"],"answer":"No sooner had we arrived","explanation":{"en":"“No sooner” first → <b>had we</b>."}}],"check":[{"id":"c1","type":"choose","prompt":{"en":"Not only ___ late, but he also forgot the tickets."},"options":["he arrived","did he arrive","he did arrive","arrived he"],"answer":1,"whys":[{"en":"“Not only” at the start needs inversion"},{"en":"✓ past simple → did + he + arrive"},{"en":"“he did arrive” keeps the subject first"},{"en":"we never move the main verb itself"}],"explanation":{"en":"“Not only” first → <b>did he arrive</b>."}},{"id":"c2","type":"choose","prompt":{"en":"Under no circumstances ___ the door."},"options":["you should open","should you open","you open","open you"],"answer":1,"whys":[{"en":"the subject can’t come first after “Under no circumstances”"},{"en":"✓ auxiliary should + you"},{"en":"normal order, no inversion"},{"en":"we never move the main verb itself"}],"explanation":{"en":"Auxiliary before the subject → <b>should you open</b>."}},{"id":"c3","type":"type","prompt":{"en":"Type the missing words (“I / realise”, past simple):"},"sentence":"Only later ___ how lucky we had been.","accept":["did I realise","did I realize"],"explanation":{"en":"Past simple, no auxiliary → <b>did I realise</b>."},"show":"did I realise"},{"id":"c4","type":"fix","prompt":{"en":"This sentence is wrong. Type its first three words correctly:"},"wrong":"Hardly I had sat down when the phone rang.","accept":["Hardly had I"],"explanation":{"en":"“Hardly” first → auxiliary before the subject: <b>Hardly had I</b>."}},{"id":"c5","type":"build","prompt":{"en":"Build the sentence:"},"tiles":["have","Never","so","I","tired","felt"],"answer":"Never have I felt so tired","explanation":{"en":"“Never” first → <b>have I felt</b>."}},{"id":"c6","type":"type","prompt":{"en":"Type the auxiliary and the subject (“we”):"},"sentence":"No sooner ___ left than it began to snow.","accept":["had we"],"explanation":{"en":"“No sooner … than” → past perfect inverted: <b>had we</b>."}},{"id":"c7","type":"choose","prompt":{"en":"Which sentence is correct?"},"options":["Only after the exam I realised my mistake.","Only after the exam did I realise my mistake."],"answer":1,"whys":[{"en":"“Only after …” needs inversion in the main clause"},{"en":"✓ inversion in the main clause: did I realise"}],"explanation":{"en":"“Only after …” → invert the main clause: <b>did I realise</b>."}}]}'::jsonb, now()
where not exists (select 1 from grammar_lesson where slug = 'c1-inversion-1');
